const iconPaths={arrow:'M5 12h14m-5-5 5 5-5 5',external:'M14 4h6v6m0-6L10 14M9 4H5a1 1 0 0 0-1 1v14a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-4',pin:'M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M13 3a4 4 0 0 1 0 8M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',calendar:'M8 2v4m8-4v4M3 10h18 M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2',home:'m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',grid:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',invite:'m3 8 18-5-5 18-4-9-9-4Zm9 4 9-9',check:'m5 12 4 4L19 6',chevron:'m9 5 7 7-7 7',close:'m6 6 12 12M6 18 18 6',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',plus:'M12 5v14M5 12h14',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M4 4l2 2M18 18l2 2M12 1v3M12 20v3M1 12h3m16 0h3M4 20l2-2M18 6l2-2',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',book:'M12 5c-3-2-7-2-10-1v16c3-1 7-1 10 1m0-16c3-2 7-2 10-1v16c-3-1-7-1-10 1V5',building:'M4 22V3h12v19M16 9h4v13M8 7h4M8 11h4M8 15h4M9 22v-3h2v3',menu:'M4 6h16M4 12h16M4 18h16',copy:'M9 9h12v12H9zM15 9V3H3v12h6',mail:'M3 5h18v14H3z m0 0 9 8 9-8',leaf:'M20 3C9 2 2 7 5 15s16 6 15-12ZM5 20 16 8'};
function icon(n){return `<svg class="icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${iconPaths[n]||iconPaths.arrow}"/></svg>`;}
function e(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function initials(name){return name.trim().split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();}
function badge(s){return `<span class="badge ${e(s)}">${e(s)}</span>`;}
function route(){const [path,query='']=(location.hash.slice(1)||'/').split('?');return {path,params:new URLSearchParams(query)};}
function go(path){if(location.hash==='#'+path)render();else location.hash=path;}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3800);}
function read(key,fallback){try{const value=localStorage.getItem(key);return value?JSON.parse(value):fallback;}catch{storageOK=false;return fallback;}}
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{storageOK=false;toast('Browser storage is unavailable. Changes last only until you reload.');return false;}}
function seed(){const fri=serviceDates('friday')[0],sun=serviceDates('sunday')[0],old=shiftDay(sun,-7),prevFri=shiftDay(fri,-7),now=new Date().toISOString();return [
 {id:'sample-1',name:'Jordan Sample',service:'sunday',date:sun,channel:'email',contact:'jordan@example.com',consent:true,host:'Unassigned',status:'Planned',source:'Member invitation',question:'Where should I meet my host?',hostRequested:true},
 {id:'sample-2',name:'Avery Example',service:'friday',date:fri,channel:'email',contact:'avery@example.com',consent:true,host:'Host A',status:'Planned',source:'Service page',question:'',hostRequested:true},
 {id:'sample-3',name:'Morgan Demo',service:'sunday',date:old,channel:'none',contact:'',consent:false,host:'Host B',status:'Attended',source:'Walk-in',question:'',attendedAt:new Date(Date.now()-72*3600000).toISOString()},
 {id:'sample-4',name:'Taylor Sample',service:'friday',date:prevFri,channel:'email',contact:'taylor@example.com',consent:true,host:'Host A',status:'Follow-up',source:'Member invitation',question:'',attendedAt:new Date(Date.now()-60*3600000).toISOString()},
 {id:'sample-5',name:'Casey Example',service:'sunday',date:shiftDay(old,-7),channel:'email',contact:'casey@example.com',consent:true,host:'Host C',status:'Connected',source:'Local search',question:'',attendedAt:new Date(Date.now()-7*86400000).toISOString(),followedUpAt:new Date(Date.now()-6*86400000).toISOString()},
 ].map(g=>({...g,sample:true,createdAt:now,history:[{at:now,text:'Illustrative demo record created.'}],...g}));}
let guests=read(KEY,null);if(!Array.isArray(guests)||guests.some(g=>!g.id||!STATUSES.includes(g.status)))guests=seed();
let readiness=read(READY_KEY,{});if(!readiness||Array.isArray(readiness)||typeof readiness!=='object')readiness={};
let installPrompt=null;
const WORK_KEY='kingsword-departments-demo-v1';
function uid(){return globalThis.crypto?.randomUUID?.()||`id-${Date.now()}-${Math.random().toString(36).slice(2)}`;}
function seedWorkspace(){const today=chicagoDay();return {currentLeaderId:null,departments:[{id:'welcome',name:'Hospitality',description:'Illustrative welcome team'},{id:'media',name:'Media & Communications',description:'Illustrative media team'},{id:'facilities',name:'Facilities',description:'Illustrative facilities team'}],leaders:[{id:'leader-welcome',name:'Jamie Demo',email:'jamie@example.com',departmentId:'welcome'},{id:'leader-media',name:'Robin Example',email:'robin@example.com',departmentId:'media'}],members:[{id:'member-w1',departmentId:'welcome',name:'Jamie Demo',email:'jamie@example.com',role:'Team leader',status:'Active',leaderId:'leader-welcome'},{id:'member-w2',departmentId:'welcome',name:'Alex Sample',email:'alex@example.com',role:'Welcome host',status:'Active'},{id:'member-m1',departmentId:'media',name:'Robin Example',email:'robin@example.com',role:'Team leader',status:'Active',leaderId:'leader-media'},{id:'member-m2',departmentId:'media',name:'Sam Demo',email:'sam@example.com',role:'Media volunteer',status:'Active'}],tasks:[{id:'task-1',departmentId:'welcome',title:'Confirm Sunday welcome hosts',description:'Review the host roster before the next service.',assigneeId:'member-w2',due:shiftDay(today,2),priority:'High',status:'To do',updatedAt:new Date().toISOString()},{id:'task-2',departmentId:'media',title:'Prepare Friday service invitation',description:'Check the service time and approved invitation link.',assigneeId:'member-m2',due:shiftDay(today,1),priority:'Normal',status:'In progress',updatedAt:new Date().toISOString()},{id:'task-3',departmentId:'facilities',title:'Review service setup checklist',description:'Illustrative planning task.',assigneeId:'',due:shiftDay(today,-1),priority:'High',status:'To do',updatedAt:new Date().toISOString()}]};}
let workspace=read(WORK_KEY,null);if(!workspace||!['departments','members','tasks','leaders'].every(k=>Array.isArray(workspace[k])))workspace=seedWorkspace();
function saveWorkspace(){write(WORK_KEY,workspace);}
function activeLeader(){return workspace.leaders.find(l=>l.id===workspace.currentLeaderId)||null;}
function selectedDepartment(){const leader=activeLeader();return leader?.departmentId||route().params.get('department')||workspace.departments[0]?.id;}
function departmentName(id){return workspace.departments.find(d=>d.id===id)?.name||'Department';}
function profileNotice(){const leader=activeLeader();return `<div class="notice neutral">${leader?`Demo leader view: <strong>${e(leader.name)}</strong> · ${e(departmentName(leader.departmentId))}.`:'Office demo view: all departments.'} Changes are saved only in this browser. Demo profiles are not real accounts or access permissions. <a class="alert-link" href="#/office/leaders">Switch demo view</a></div>`;}
function departmentCards(){const leader=activeLeader(),depts=workspace.departments.filter(d=>!leader||d.id===leader.departmentId);return `<div class="department-grid">${depts.map(d=>{const summary=departmentSummary(workspace,d.id,chicagoDay()),leads=workspace.leaders.filter(l=>l.departmentId===d.id);return `<article class="panel department-card"><div class="department-symbol">${icon('people')}</div><h3>${e(d.name)}</h3><p>${leads.map(l=>e(l.name)).join(', ')||'Leader not assigned'} <span class="muted-label">· Demo</span></p><div class="department-stats"><span><strong>${summary.members}</strong> members</span><span><strong>${summary.open}</strong> open tasks</span><span class="${summary.overdue?'overdue-text':''}"><strong>${summary.overdue}</strong> overdue</span></div><div class="invite-actions"><a class="btn outline small" href="#/office/team?department=${e(d.id)}">Manage team ${icon('arrow')}</a><a class="text-link" href="#/office/tasks?department=${e(d.id)}">Tasks ${icon('chevron')}</a></div></article>`;}).join('')}</div>`;}
function officeWorkspace(){const leader=activeLeader(),summary=departmentSummary(workspace,leader?.departmentId,chicagoDay());return officeShell(`${officeHeading(leader?`Welcome, ${e(leader.name.split(' ')[0])}.`:'Your church office, connected.','A shared view of departments, people, responsibilities, and the week ahead.',`<a class="btn outline small" href="#/welcome">Visitor website ${icon('external')}</a><button class="btn outline small" data-action="install">${icon('download')} Add to home screen</button><a class="btn small" href="#/office/leaders">${icon('plus')} Leader demo</a>`)}${profileNotice()}<div class="metrics">${metric('Departments',leader?1:workspace.departments.length,'Illustrative ministry teams','building')}${metric('Active team members',summary.members,'Across the selected demo view','people')}${metric('Open tasks',summary.open,`${summary.overdue} past their due date`,'calendar',true)}${metric('Completed tasks',summary.done,'Recorded in this browser','check')}</div><div class="section-head" style="margin-bottom:18px"><div><h2 style="font-size:21px">Departments at a glance</h2></div><a class="text-link" href="#/office/departments">View departments ${icon('arrow')}</a></div>${departmentCards()}<div class="office-banner"><div><h3>From a clear owner to a completed task.</h3><p>Try creating a leader demo profile, adding sample teammates, and assigning a task. Office view brings the departments together; leader view focuses on one team.</p></div><a class="btn outline small" href="#/office/tasks">Open task board ${icon('arrow')}</a></div><h2 class="office-section-title">Office tools</h2><div class="coord-grid">${[['people','Guest care & follow-up','Visitor plans, host assignments, and Connect handoffs.','guests'],['calendar','Six-week calendar','Weekly service dates and readiness checklists.','calendar'],['invite','Service invitation kit','Shareable Sunday and Friday invitation materials.','invitations']].map(([ic,t,d,page])=>`<a class="coord-card" href="#/office/${page}">${icon(ic)}<h3>${t}</h3><p>${d}</p></a>`).join('')}</div>`);}
function departmentsPage(){return officeShell(`${officeHeading('Departments & responsibilities','Office oversight with a focused workspace for each department.',`<a class="btn small" href="#/office/leaders">${icon('plus')} Create leader demo</a>`)}${profileNotice()}${departmentCards()}<div class="office-banner"><div><h3>Built around the office structure.</h3><p>The Office Administrative Lead oversees member services, facilities, and calendar/programs/communications. Department teams manage their own people and work within that operating model.</p></div></div>`,'departments');}
function departmentSelect(id,elementId='team-department'){return `<label class="sr-only" for="${elementId}">Department</label><select id="${elementId}" ${activeLeader()?'disabled':''}>${workspace.departments.filter(d=>!activeLeader()||d.id===activeLeader().departmentId).map(d=>`<option value="${e(d.id)}" ${d.id===id?'selected':''}>${e(d.name)}</option>`).join('')}</select>`;}
function teamPage(){const id=selectedDepartment(),members=workspace.members.filter(m=>m.departmentId===id);return officeShell(`${officeHeading('Your team, in one place.',e(departmentName(id)),`<button class="btn small" data-action="member-add" data-department="${e(id)}">${icon('plus')} Add demo member</button>`)}${profileNotice()}<section class="panel"><div class="toolbar">${departmentSelect(id)}<span class="muted-label">${members.filter(m=>m.status==='Active').length} active members · sample records only</span></div><div class="table-scroll"><table><caption class="sr-only">Department team roster</caption><thead><tr><th>Team member</th><th>Responsibility</th><th>Status</th><th>Open tasks</th><th>Actions</th></tr></thead><tbody>${members.length?members.map(m=>`<tr><td><div class="person-cell"><span class="avatar">${e(initials(m.name))}</span><div><strong>${e(m.name)}</strong><small>${e(m.email||'No contact provided')}</small></div></div></td><td>${e(m.role)}</td><td>${badge(m.status)}</td><td>${workspace.tasks.filter(t=>t.assigneeId===m.id&&t.status!=='Done').length}</td><td><button class="row-button" data-action="member-edit" data-id="${e(m.id)}">Edit ${icon('chevron')}</button></td></tr>`).join(''):'<tr><td colspan="5"><div class="empty"><h3>Make room for your team.</h3><p>Add a sample member to start assigning responsibilities.</p></div></td></tr>'}</tbody></table></div></section><div class="office-banner"><div><h3>People first. Clear responsibilities next.</h3><p>Pause a member to keep their record without assigning new work. Reassign their open tasks before changing their availability.</p></div><a class="btn outline small" href="#/office/tasks?department=${e(id)}">Manage team tasks ${icon('arrow')}</a></div>`,'team');}
function memberModal(id,departmentId){const member=workspace.members.find(m=>m.id===id),dept=member?.departmentId||departmentId;if(activeLeader()&&dept!==activeLeader().departmentId)return;openOverlay(`<div class="drawer-header"><h2 id="dialog-title">${member?'Edit':'Add'} demo team member</h2><button class="icon-btn" data-action="close" aria-label="Close">${icon('close')}</button></div><p>${e(departmentName(dept))} · Use fictional names and contacts.</p><form id="member-form"><input type="hidden" name="id" value="${e(member?.id||'')}"><input type="hidden" name="departmentId" value="${e(dept)}"><div class="fields"><div class="field full"><label for="member-name">Name</label><input id="member-name" name="name" maxlength="100" value="${e(member?.name||'')}" required></div><div class="field full"><label for="member-email">Sample email <span class="muted-label">Optional</span></label><input id="member-email" type="email" name="email" value="${e(member?.email||'')}" maxlength="150" placeholder="sample@example.com"></div><div class="field full"><label for="member-role">Responsibility</label><input id="member-role" name="role" maxlength="80" value="${e(member?.role||'Team member')}" required></div><div class="field full"><label for="member-status">Availability</label><select id="member-status" name="status"><option ${member?.status==='Active'?'selected':''}>Active</option><option ${member?.status==='Paused'?'selected':''}>Paused</option></select></div></div><button class="btn form-submit">Save demo member ${icon('check')}</button></form>`,true);}
let taskFilter='all';
function tasksPage(){const id=selectedDepartment(),tasks=workspace.tasks.filter(t=>t.departmentId===id&&(taskFilter==='all'||t.priority===taskFilter));return officeShell(`${officeHeading('Turn plans into progress.',e(departmentName(id))+' · Assign work, track due dates, and close the loop.',`<button class="btn small" data-action="task-add" data-department="${e(id)}">${icon('plus')} New task</button>`)}${profileNotice()}<div class="panel" style="margin-bottom:20px"><div class="toolbar">${departmentSelect(id,'task-department')}<label class="sr-only" for="task-priority-filter">Priority filter</label><select id="task-priority-filter"><option value="all">All priorities</option>${['High','Normal'].map(p=>`<option ${taskFilter===p?'selected':''}>${p}</option>`).join('')}</select><span class="muted-label">${tasks.length} tasks · saved in this browser</span></div></div><div class="task-board">${TASK_STATUSES.map(status=>`<section class="task-column"><div class="task-column-head"><h2>${status}</h2><span>${tasks.filter(t=>t.status===status).length}</span></div>${tasks.filter(t=>t.status===status).map(t=>{const member=workspace.members.find(m=>m.id===t.assigneeId),late=t.due&&t.due<chicagoDay()&&t.status!=='Done';return `<article class="task-card"><div class="task-card-top"><span class="badge ${t.priority==='High'?'Follow-up':''}">${t.priority} priority</span><button class="row-button" data-action="task-edit" data-id="${e(t.id)}" aria-label="Edit ${e(t.title)}">Edit</button></div><h3>${e(t.title)}</h3>${t.description?`<p>${e(t.description)}</p>`:''}<div class="task-owner">${icon('people')} ${e(member?.name||'Unassigned')}${member?.status==='Paused'?' · paused':''}</div><div class="task-due ${late?'overdue-text':''}">${icon('calendar')} ${t.due?dateLabel(t.due,{month:'short',day:'numeric',year:'numeric'}):'No due date'}${late?' · overdue':''}</div><label class="sr-only" for="status-${e(t.id)}">Status for ${e(t.title)}</label><select class="task-status" id="status-${e(t.id)}" data-task-status="${e(t.id)}">${TASK_STATUSES.map(s=>`<option ${s===status?'selected':''}>${s}</option>`).join('')}</select></article>`;}).join('')||'<div class="task-empty">No tasks in this stage.</div>'}</section>`).join('')}</div>`,'tasks');}
function taskModal(id,departmentId){const task=workspace.tasks.find(t=>t.id===id),dept=task?.departmentId||departmentId;if(activeLeader()&&dept!==activeLeader().departmentId)return;const members=workspace.members.filter(m=>m.departmentId===dept&&m.status==='Active');openOverlay(`<div class="drawer-header"><h2 id="dialog-title">${task?'Edit':'Create'} a task</h2><button class="icon-btn" data-action="close" aria-label="Close">${icon('close')}</button></div><p>${e(departmentName(dept))} · Give each task a clear owner and next step.</p><form id="task-form" novalidate><input type="hidden" name="id" value="${e(task?.id||'')}"><input type="hidden" name="departmentId" value="${e(dept)}"><div id="task-errors" role="alert"></div><div class="fields"><div class="field full"><label for="task-title">Task title</label><input id="task-title" name="title" maxlength="140" value="${e(task?.title||'')}" required></div><div class="field full"><label for="task-description">Details <span class="muted-label">Optional</span></label><textarea id="task-description" name="description" maxlength="500" placeholder="Keep private member and pastoral details out of this demo.">${e(task?.description||'')}</textarea></div><div class="field full"><label for="task-assignee">Assign to</label><select id="task-assignee" name="assigneeId"><option value="">Unassigned</option>${members.map(m=>`<option value="${e(m.id)}" ${task?.assigneeId===m.id?'selected':''}>${e(m.name)}</option>`).join('')}</select></div><div class="field"><label for="task-due">Due date</label><input id="task-due" type="date" name="due" value="${e(task?.due||'')}"></div><div class="field"><label for="task-priority">Priority</label><select id="task-priority" name="priority"><option>Normal</option><option ${task?.priority==='High'?'selected':''}>High</option></select></div><div class="field full"><label for="task-status">Status</label><select id="task-status" name="status">${TASK_STATUSES.map(s=>`<option ${task?.status===s?'selected':''}>${s}</option>`).join('')}</select></div></div><button class="btn form-submit">Save task ${icon('check')}</button></form>`,true);}
function leadersPage(){const leader=activeLeader();return officeShell(`${officeHeading('A workspace for every leader.','Try department leadership with a local demo profile. No password or real account is created.')}<div class="settings-grid"><section class="panel settings-panel"><div class="eyebrow">Leader demo setup</div><h2 style="margin-top:15px">Create a demo leader profile</h2><p>This demonstrates the sign-up journey. Use a sample name and email. Profiles, teams, and tasks stay on this browser and are not shared with the office.</p><form id="leader-form" novalidate style="margin-top:20px"><div id="leader-errors" role="alert"></div><div class="fields"><div class="field full"><label for="leader-name">Leader name</label><input id="leader-name" name="name" maxlength="100" required placeholder="Demo Leader"></div><div class="field full"><label for="leader-email">Sample email</label><input id="leader-email" name="email" type="email" required placeholder="leader@example.com"></div><div class="field full"><label for="leader-department">Department</label><input id="leader-department" name="department" list="department-options" maxlength="70" placeholder="Choose or name a department" required><datalist id="department-options">${workspace.departments.map(d=>`<option value="${e(d.name)}"></option>`).join('')}</datalist></div></div><button class="btn form-submit">Create demo profile ${icon('arrow')}</button></form></section><section class="panel settings-panel"><h2>Switch the demo perspective</h2><p>Currently: <strong>${leader?e(leader.name)+' · '+e(departmentName(leader.departmentId)):'Office Administrative Lead'}</strong>. These are presentation views, not authorization roles.</p><div class="leader-list"><button class="leader-switch" data-action="leader-switch" data-id="office">${icon('building')}<span><strong>Office Administrative Lead</strong><small>All departments and office tools</small></span>${icon('arrow')}</button>${workspace.leaders.map(l=>`<button class="leader-switch" data-action="leader-switch" data-id="${e(l.id)}"><span class="avatar">${e(initials(l.name))}</span><span><strong>${e(l.name)}</strong><small>${e(departmentName(l.departmentId))}</small></span>${icon('arrow')}</button>`).join('')}</div><div class="notice" style="margin-top:22px">Production sign-up requires verified identity, office approval of department access, server-enforced permissions, and a shared database. The public demo grants no real church access.</div></section></div>`,'leaders');}
function handleWorkspaceAction(action,el){if(action==='install'){if(installPrompt){installPrompt.prompt();installPrompt=null;}else openOverlay(`<div class="drawer-header"><h2 id="dialog-title">Add KingsWord to your home screen</h2><button class="icon-btn" data-action="close" aria-label="Close">${icon('close')}</button></div><p>On iPhone or iPad, open this public link in Safari, tap Share, then Add to Home Screen. On Android or desktop Chrome/Edge, use Install app or Add to Home Screen in the browser menu when available.</p><div class="notice neutral">The installed app is the same demo. Records stay on this device; installation does not enable real accounts, shared team data, or messaging. Open once online before trying cached pages offline.</div>`,true);return true;}const id=el.dataset.id,dept=el.dataset.department;if(action==='member-add'){memberModal(null,dept);return true;}if(action==='member-edit'){memberModal(id);return true;}if(action==='task-add'){taskModal(null,dept);return true;}if(action==='task-edit'){taskModal(id);return true;}if(action==='leader-switch'){if(id!=='office'&&!workspace.leaders.some(l=>l.id===id))return true;workspace.currentLeaderId=id==='office'?null:id;saveWorkspace();go('/office');toast('Demo perspective changed. No account sign-in occurred.');return true;}return false;}
function handleWorkspaceSubmit(form){if(!['leader-form','member-form','task-form'].includes(form.id))return false;const values=Object.fromEntries(new FormData(form));
 if(form.id==='leader-form'){const errors=validateLeader(values);if(Object.keys(errors).length){form.querySelector('#leader-errors').innerHTML=`<div class="notice">${Object.values(errors).map(e).join('<br>')}</div>`;return true;}if(workspace.leaders.some(l=>l.email.toLowerCase()===values.email.trim().toLowerCase())){form.querySelector('#leader-errors').innerHTML='<div class="notice">A demo profile with that email already exists. Use Switch the demo perspective.</div>';return true;}let dept=workspace.departments.find(d=>d.name.toLowerCase()===values.department.trim().toLowerCase());if(!dept){dept={id:uid(),name:values.department.trim(),description:'Department created in this demo'};workspace.departments.push(dept);}const leader={id:uid(),name:values.name.trim(),email:values.email.trim(),departmentId:dept.id};workspace.leaders.push(leader);workspace.members.push({id:uid(),departmentId:dept.id,name:leader.name,email:leader.email,role:'Team leader',status:'Active',leaderId:leader.id});workspace.currentLeaderId=leader.id;saveWorkspace();go('/office/team');toast('Demo profile created. Your team workspace is ready.');return true;}
 const dept=values.departmentId;if(!workspace.departments.some(d=>d.id===dept)||(activeLeader()&&activeLeader().departmentId!==dept)){toast('Select your demo department.');return true;}
 if(form.id==='member-form'){if(!values.name?.trim()||values.name.trim().length>100||!values.role?.trim()||values.role.trim().length>80||!['Active','Paused'].includes(values.status)||(values.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email))){toast('Check the member name, responsibility, email, and status.');return true;}const existing=workspace.members.find(m=>m.id===values.id);if(existing&&existing.departmentId!==dept)return true;const member={...existing,id:existing?.id||uid(),departmentId:dept,name:values.name.trim(),email:(values.email||'').trim(),role:values.role.trim(),status:values.status};if(existing)workspace.members[workspace.members.indexOf(existing)]=member;else workspace.members.push(member);saveWorkspace();closeOverlay();render();toast('Demo team member saved.');return true;}
 if(form.id==='task-form'){const errors=validateTask(values,workspace.members);if(Object.keys(errors).length){form.querySelector('#task-errors').innerHTML=`<div class="notice">${Object.values(errors).map(e).join('<br>')}</div>`;return true;}const existing=workspace.tasks.find(t=>t.id===values.id);if(existing&&existing.departmentId!==dept)return true;const task={...values,id:existing?.id||uid(),title:values.title.trim(),description:(values.description||'').trim(),updatedAt:new Date().toISOString()};if(existing)workspace.tasks[workspace.tasks.indexOf(existing)]=task;else workspace.tasks.unshift(task);saveWorkspace();closeOverlay();render();toast('Task saved in this browser.');return true;}return false;}

function persist(){write(KEY,guests);}
function brand(office=false){return `<a class="brand" href="${office?'#/office':'#/welcome'}" aria-label="KingsWord Chicago home"><img src="./assets/mark.svg" alt=""><span><strong>KINGSWORD</strong><small>${office?'CHURCH OFFICE':'CHICAGO · THE APOSTOLIC PLACE'}</small></span></a>`;}
function publicHeader(){return `<div class="preview-label">PUBLIC DEMO · Sample data only · No messages are sent</div><header class="public-header wrap">${brand()}<nav class="public-nav" aria-label="Main navigation"><a class="desktop-link" href="#/visit/sunday">Sundays</a><a class="desktop-link" href="#/visit/friday">Fridays</a><a class="staff-link" href="#/office">Office demo</a><a class="btn small" href="#/plan">Plan a visit ${icon('arrow')}</a></nav></header>`;}
function footer(){return `<footer class="public-footer wrap"><span>© ${new Date().getFullYear()} KingsWord Chicago · Working concept</span><div><a href="https://chicago.kingsword.org/" target="_blank" rel="noopener noreferrer">Official church website ${icon('external')}</a><a href="#/office">Office demo</a></div></footer>`;}
function art(){return `<div class="hero-art" role="img" aria-label="An abstract golden sunrise framed by flowing lines"><span class="art-top">WORD · SPIRIT · COMMUNITY</span><svg class="art-lines" viewBox="0 0 500 530" preserveAspectRatio="none" aria-hidden="true"><g fill="none" stroke="#e0cb97" stroke-width=".65" opacity=".4">${Array.from({length:15},(_,i)=>`<path d="M${-110+i*23} 560 Q${490-i*8} ${360-i*8} ${130+i*15} -20"/>`).join('')}${Array.from({length:8},(_,i)=>`<path d="M-30 ${265+i*22} Q${210+i*12} ${190+i*19} 520 ${455+i*13}"/>`).join('')}</g></svg><div class="art-label"><strong>Faith for life.<br>Room for you.</strong><span>CHICAGO, IL<br>4250 W WALTON ST</span></div></div>`;}
function dateTile(date){return `<div class="date-tile"><small>${dateLabel(date,{month:'short'})}</small><strong>${dateLabel(date,{day:'numeric'})}</strong></div>`;}
function home(){return `${publicHeader()}<main id="main" class="wrap"><section class="hero"><div class="hero-copy"><div class="eyebrow">Welcome to KingsWord Chicago</div><h1>Faith grows here.<br>So can <em>you.</em></h1><p>A place to encounter God’s Word, find community, and take your next step. There’s room for you this Sunday—and this Friday.</p><div class="hero-actions"><a class="btn" href="#/plan">Come as you are ${icon('arrow')}</a><a class="text-link" href="#/welcome" data-action="services">Explore our services ${icon('chevron')}</a></div><a class="location-line" href="${DIRECTIONS}" target="_blank" rel="noopener noreferrer">${icon('pin')}4250 W Walton Street, Chicago, IL</a></div>${art()}</section><div class="service-strip"><span><strong>SUNDAYS</strong><i class="dot"></i>10:00 AM</span><span><strong>FRIDAYS</strong><i class="dot"></i>7:30 PM</span><span>${icon('pin')} Chicago, Illinois</span><span>One community. A place for you.</span></div><section class="section" id="services"><div class="section-head"><div><div class="eyebrow">Make room for community</div><h2>Two moments to connect.</h2></div><p>Find your rhythm. Join us in person for a weekly service at KingsWord Chicago.</p></div><div class="service-cards">${Object.entries(SERVICES).map(([key,s],i)=>`<article class="service-card ${key}"><div class="card-top"><span class="day">Every ${key}</span><span class="number">0${i+1}</span></div><h3>${s.name}</h3><div class="service-time">${s.time} <span class="muted-label">Chicago time</span></div><p>${s.short}</p><div class="card-foot"><a class="text-link" href="#/visit/${key}">Discover ${key}s ${icon('arrow')}</a><span class="chip">Next: ${dateLabel(serviceDates(key)[0])}</span></div></article>`).join('')}</div></section></main><section class="welcome-section section"><div class="wrap welcome-grid"><div><div class="eyebrow">Your first time, made simple</div><h2>You don’t have to<br>figure it out alone.</h2><p>A new place can feel unfamiliar. Find the practical details before you come, or let us know you’d like someone to meet you.</p></div><div class="welcome-points">${[['pin','Easy to find','4250 W Walton Street, with parking in the lot adjacent to the church.'],['people','A warm welcome','Choose to plan your visit and request a friendly host to meet you.'],['heart','Room for families','Childcare is listed for Sunday services. Contact the office for age-specific details.'],['book','Come ready to grow','Explore biblical teaching, worship, and the next steps available at KingsWord.']].map(([ic,t,d])=>`<div class="welcome-point"><div class="icon-wrap">${icon(ic)}</div><h3>${t}</h3><p>${d}</p></div>`).join('')}</div></div></section><div class="wrap"><section class="visit-banner"><div><h2>Your next step can be simple.</h2><p>Choose a service. Find your way here. We’ll take it from there.</p></div><a class="btn gold" href="#/plan">Plan your first visit ${icon('arrow')}</a></section></div>${footer()}`;}
function visit(kind){const s=SERVICES[kind],date=serviceDates(kind)[0];return `${publicHeader()}<main id="main" class="wrap"><div class="page-intro"><a class="back-link" href="#/welcome">← Back to welcome</a><div class="eyebrow" style="margin-top:25px">${s.eyebrow}</div><h1>See you ${kind}.</h1><p>${s.description}</p></div><div class="visit-layout"><div class="visit-copy"><h2 style="font-size:30px;margin-bottom:20px">A little less unknown.<br>A little more welcome.</h2><p style="font-size:14px;margin-bottom:28px">Whether you’re exploring faith, looking for a church, or joining a friend, you’re welcome here. You can arrive without registering.</p>${[
 ['What should I wear?','Come in something you feel comfortable wearing. The church FAQ describes a modest, respectful approach rather than a strict dress code.'],
 ['Where do I park?','The church lists parking in the lot adjacent to 4250 W Walton Street. If you request a host, you can ask for arrival help.'],
 ['Can I bring my children?',kind==='sunday'?'The church lists childcare for Sunday services. Check with the office for age groups, check-in details, and any current arrangements.':'Families are welcome to inquire. Friday childcare arrangements have not been confirmed for this preview. Contact the office before relying on childcare.'],
 ['Do I need to book a place?','No. The optional visit planner helps the team prepare a welcome. It is not a ticket or a requirement to attend.'],
 ['How long is the service?','An end time has not been confirmed. Contact the church office if you need to plan around a specific departure time.'],
 ['Can I talk to someone first?','The church office lists admin@kingsword.org and +1 773 277 8701. This preview does not send messages or book a host with the real team.']
 ].map(([q,a])=>`<details class="faq"><summary>${q}</summary><p>${a}</p></details>`).join('')}</div><aside class="visit-info"><h3>${s.name}</h3><div class="detail-row">${icon('calendar')}<div><small>Next gathering</small><strong>${dateLabel(date,{weekday:'long',month:'long',day:'numeric'})}</strong><p>${s.time} · America/Chicago</p></div></div><div class="detail-row">${icon('pin')}<div><small>Meet us here</small><strong>4250 W Walton Street</strong><p>Chicago, IL 60651 · Adjacent parking</p></div></div><div class="detail-row">${icon('people')}<div><small>Your welcome</small><strong>You can come just as you are.</strong><p>No reservation required.</p></div></div><a class="btn gold" href="#/plan?service=${kind}">Plan a ${kind} visit ${icon('arrow')}</a><a class="btn light" href="${DIRECTIONS}" target="_blank" rel="noopener noreferrer">Get directions ${icon('external')}</a><button class="btn light" data-action="calendar" data-service="${kind}" data-date="${date}">Add to calendar ${icon('calendar')}</button><p style="font-size:10px;margin-top:14px">Regular schedule shown. Check the official website for special-service changes. Calendar uses a one-hour placeholder, not a confirmed end time.</p></aside></div></main>${footer()}`;}
function planForm(kind='sunday',source='Service page'){return `<form id="plan-form" novalidate><input type="hidden" name="source" value="${e(source)}"><div id="plan-errors" role="alert"></div><div class="fields"><div class="field full"><label for="guest-name">Your name</label><input id="guest-name" name="name" autocomplete="name" maxlength="100" placeholder="Use a sample name for this preview" required></div><div class="field"><label for="plan-service">I’m visiting on</label><select id="plan-service" name="service">${Object.entries(SERVICES).map(([k,s])=>`<option value="${k}" ${kind===k?'selected':''}>${s.name}</option>`).join('')}</select></div><div class="field"><label for="plan-date">Choose a date</label><select id="plan-date" name="date">${dateOptions(kind)}</select></div><div class="field full"><label for="plan-channel">How may we contact you about your visit?</label><select id="plan-channel" name="channel"><option value="none">No contact — I just need the details</option><option value="email">Email</option><option value="phone">Phone</option></select></div><div class="field full" id="contact-field" hidden><label id="contact-label" for="plan-contact">Email address</label><input id="plan-contact" name="contact" type="email" placeholder="you@example.com" maxlength="150"></div><div class="field full"><label for="plan-question">Any arrival questions? <span class="muted-label">Optional</span></label><textarea id="plan-question" name="question" maxlength="500" placeholder="For example, where to meet your host. Please leave out private care or prayer details."></textarea></div></div><label class="check"><input type="checkbox" name="hostRequested">I’d like someone to welcome me when I arrive.</label><label class="check" id="consent-field" hidden><input type="checkbox" name="consent">I agree to be contacted about this visit through my selected channel. This preview sends no messages.</label><button type="submit" class="btn form-submit">Save my demo visit ${icon('arrow')}</button><p class="help" style="font-size:10px;text-align:center;margin-top:12px;color:var(--muted)">Not required to attend. Demo details stay in this browser.</p></form>`;}
function dateOptions(kind){return serviceDates(kind).map(d=>`<option value="${d}">${dateLabel(d,{weekday:'short',month:'short',day:'numeric'})} · ${SERVICES[kind].time}</option>`).join('');}
function plan(){const {params}=route(),kind=SERVICES[params.get('service')]?params.get('service'):'sunday',source=params.get('source')==='member'?'Member invitation':'Service page';return `${publicHeader()}<main id="main" class="wrap"><div class="plan-layout"><div class="plan-copy"><a class="back-link" href="#/welcome">← Back to welcome</a><div class="eyebrow" style="margin-top:35px">Let’s make your first visit easy</div><h1>A place for you.<br>A plan to get here.</h1><p>Choose a gathering and find the details you need. Want a friendly face to meet you? You can ask for that, too.</p><a class="location-line" href="${DIRECTIONS}" target="_blank" rel="noopener noreferrer">${icon('pin')}4250 W Walton Street, Chicago</a><div class="steps">${[['Choose your service','Sunday at 10 a.m. or Friday at 7:30 p.m.'],['Let us know what helps','Arrival information, a host, or simply directions.'],['Come as you are','Planning is optional. You are welcome either way.']].map(([t,d],i)=>`<div><span>0${i+1}</span><div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}</div></div><div class="form-card" id="plan-card"><h2>Plan your visit</h2><p>A few details. A warmer welcome.</p><div class="notice">You’re trying a working preview. Use sample details only. This saves to this browser and does not notify the church or reserve a real host.</div>${planForm(kind,source)}</div></div></main>${footer()}`;}
function publicSuccess(g){document.querySelector('#plan-card').innerHTML=`<div class="success"><div class="success-icon">${icon('check')}</div><div class="eyebrow" style="justify-content:center;margin-bottom:15px">Demo visit saved</div><h2>There’s a place for you, ${e(g.name.split(' ')[0])}.</h2><p>Your sample visit is ready in the office demo. Nothing has been sent to the church.</p><div class="visit-summary"><strong>${SERVICES[g.service].name} · ${dateLabel(g.date,{month:'long',day:'numeric'})}</strong><p>${SERVICES[g.service].time} Chicago time<br>4250 W Walton Street, Chicago, IL 60651</p><p>${g.hostRequested?'Welcome host requested in this demo.':'No host requested.'} ${g.channel==='none'?'No contact requested.':'Visit-contact permission recorded.'}</p></div><div class="actions"><button class="btn" data-action="calendar" data-service="${g.service}" data-date="${g.date}">Save to calendar ${icon('calendar')}</button><a class="btn outline" href="${DIRECTIONS}" target="_blank" rel="noopener noreferrer">Directions ${icon('pin')}</a></div><div class="confirmation-actions" style="justify-content:center"><a class="text-link" href="#/office/guests">See this visit in the office demo ${icon('arrow')}</a><button class="plain" data-action="cancel-own" data-id="${e(g.id)}">Cancel demo visit</button></div><p class="subtle" style="margin-top:23px">Calendar end time is a one-hour placeholder. Confirm current service details with the official church office.</p></div>`;document.querySelector('#plan-card').scrollIntoView({behavior:'smooth',block:'start'});}
function overdue(g){return g.attendedAt&&!g.followedUpAt&&g.status!=='Cancelled'&&g.status!=='Connected'&&Date.now()-new Date(g.attendedAt).getTime()>48*3600000;}
function pending(){return guests.filter(g=>g.attendedAt&&!g.followedUpAt&&!['Connected','Cancelled'].includes(g.status));}
function saveGuest(g){const idx=guests.findIndex(v=>v.id===g.id);if(idx<0)guests.unshift(g);else guests[idx]=g;persist();}
function officeShell(content,active='overview'){const nav=[['overview','grid','Overview','/office'],['departments','building','Departments','/office/departments'],['team','people','Team members','/office/team'],['tasks','check','Tasks & responsibilities','/office/tasks'],['leaders','people','Leader demo setup','/office/leaders'],['guests','people','Guests & follow-up','/office/guests'],['calendar','calendar','Six-week calendar','/office/calendar'],['invitations','invite','Invitation kit','/office/invitations'],['settings','settings','Demo & setup','/office/settings']];return `<div class="office-layout"><aside class="sidebar" aria-label="Office navigation">${brand(true)}<div class="sidebar-label">Office workspace</div><nav class="side-nav">${nav.map(([id,ic,t,path])=>`<a href="#${path}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(ic)}${t}${id==='guests'?`<span class="nav-count">${guests.length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><a href="#/welcome">${icon('external')}View visitor website</a><div class="profile"><span class="avatar">OL</span><div>${activeLeader()?e(activeLeader().name):'Office Administrative Lead'}<small>${activeLeader()?e(departmentName(activeLeader().departmentId)):'Demo workspace · sample access'}</small></div></div></div></aside><div class="office-main"><header class="office-top"><button class="mobile-menu" data-action="menu" aria-label="Open office navigation" aria-expanded="false">${icon('menu')}</button><span>KingsWord Chicago <span style="padding:0 8px;color:#bdc6bc">/</span> <strong>Church office</strong></span><div class="top-right"><span class="subtle">${new Intl.DateTimeFormat('en-US',{timeZone:TIMEZONE,weekday:'short',month:'short',day:'numeric'}).format(new Date())}</span><span class="demo-pill">Browser-only demo</span></div></header><main id="main" class="office-content">${content}</main></div></div>`;}
function officeHeading(title,desc,actions=''){return `<div class="office-heading"><div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function officeNotice(){return `<div class="notice neutral">All people and activity shown are illustrative. Records stay in this browser. <a class="alert-link" href="#/office/settings">See demo limits & next steps</a></div>`;}
function metric(label,value,note,ic,hl=false){return `<div class="metric ${hl?'highlight':''}"><div class="metric-label">${label}${icon(ic)}</div><div class="metric-number">${value}</div><div class="metric-foot">${note}</div></div>`;}
function miniGuest(g){return `<button class="guest-mini" data-action="guest" data-id="${e(g.id)}"><span class="avatar">${e(initials(g.name))}</span><div><div class="guest-name">${e(g.name)}</div><div class="guest-meta">${SERVICES[g.service].name} · ${dateLabel(g.date)} · ${e(g.host)}</div></div>${overdue(g)?'<span class="badge Follow-up">Follow-up due</span>':badge(g.status)}</button>`;}
function overview(){const planned=guests.filter(g=>g.status==='Planned'&&g.date>=chicagoDay()),due=pending(),assigned=planned.filter(g=>g.host!=='Unassigned'),attention=[...guests].filter(g=>overdue(g)||(g.status==='Planned'&&g.host==='Unassigned')).sort((a,b)=>Number(overdue(b))-Number(overdue(a))).slice(0,4);return officeShell(`${officeHeading('A clear view. A caring next step.','Your people, your services, and what needs attention.',`<a class="btn outline small" href="#/office/calendar">${icon('calendar')} Calendar</a><button class="btn small" data-action="add-guest">${icon('plus')} Add demo guest</button>`)}${officeNotice()}<div class="metrics">${metric('Upcoming visits',planned.length,'Planned for upcoming services','people')}${metric('Follow-up needed',due.length,`${due.filter(overdue).length} past the 48-hour window`,'heart',true)}${metric('Hosts assigned',assigned.length,`Of ${planned.length} upcoming visit plans`,'check')}${metric('Connect handoffs',guests.filter(g=>g.status==='Connected').length,'Marked connected in this demo','leaf')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>People to check in with</h2><a class="text-link" href="#/office/guests">All guests ${icon('arrow')}</a></div>${attention.length?attention.map(miniGuest).join(''):'<div class="empty"><h3>You’re up to date.</h3><p>No unassigned visits or overdue follow-ups.</p></div>'}<div class="panel-note">Personal follow-through starts with a named owner.</div></section><section class="panel"><div class="panel-head"><h2>The next gatherings</h2><a class="text-link" href="#/office/calendar">Six weeks ${icon('arrow')}</a></div>${Object.entries(SERVICES).map(([k,s])=>({k,s,date:serviceDates(k)[0]})).sort((a,b)=>a.date.localeCompare(b.date)).map(({k,s,date})=>`<div class="service-mini">${dateTile(date)}<div><h3>${s.name}</h3><p>${s.time} · 4250 W Walton Street</p><div class="mini-bottom">${icon('people')}${guests.filter(g=>g.service===k&&g.date===date&&g.status!=='Cancelled').length} demo visit plans <a href="#/office/calendar" class="text-link" style="font-size:9px">Readiness ${icon('chevron')}</a></div></div></div>`).join('')}</section></div><div class="office-banner"><div><h3>A simple invitation can open a door.</h3><p>Give members a service-specific link and a message they can make their own. Then make the welcome count.</p></div><a class="btn outline small" href="#/office/invitations">Open invitation kit ${icon('arrow')}</a></div><h2 class="office-section-title">One office. Three connected responsibilities.</h2><div class="coord-grid">${[['people','Member & Volunteer Services','Guest follow-up, host assignments, and next steps.','guests'],['building','Facilities & Building Operations','Arrival, parking, and service setup readiness.','calendar'],['calendar','Calendar, Programs & Communications','Six-week outlook and service invitation links.','invitations']].map(([ic,t,d,page])=>`<a class="coord-card" href="#/office/${page}">${icon(ic)}<h3>${t}</h3><p>${d}</p></a>`).join('')}</div>`);}
function filteredGuests(){return guests.filter(g=>(filter.service==='all'||g.service===filter.service)&&(filter.status==='all'||(filter.status==='due'?overdue(g):g.status===filter.status))&&`${g.name} ${g.contact} ${g.host}`.toLowerCase().includes(filter.query.toLowerCase()));}
function guestRows(){const list=filteredGuests();return list.length?list.map(g=>`<tr><td><div class="person-cell"><span class="avatar">${e(initials(g.name))}</span><div><strong>${e(g.name)}</strong><small>${g.channel==='none'?'No contact requested':e(g.contact)}</small></div></div></td><td>${SERVICES[g.service].name}<div class="subtle">${dateLabel(g.date,{month:'short',day:'numeric',year:'numeric'})}</div></td><td>${badge(g.status)}${overdue(g)?'<div class="subtle" style="color:#96732b;margin-top:4px">Follow-up overdue</div>':''}</td><td>${e(g.host)}</td><td>${e(g.source)}</td><td><button class="row-button" data-action="guest" data-id="${e(g.id)}" aria-label="Open ${e(g.name)}">View ${icon('chevron')}</button></td></tr>`).join(''):`<tr><td colspan="6"><div class="empty">${icon('search')}<h3>No guests match this view.</h3><p>Try another search or clear your filters.</p><button class="btn outline small" data-action="clear-filters">Clear filters</button></div></td></tr>`;}
function guestPage(){return officeShell(`${officeHeading('Guests & follow-up','Every person has a name. Every welcome has a next step.',`<button class="btn outline small" data-action="export">${icon('download')} Export CSV</button><button class="btn small" data-action="add-guest">${icon('plus')} Add demo guest</button>`)}${officeNotice()}<section class="panel"><div class="toolbar"><div class="search">${icon('search')}<label class="sr-only" for="guest-search">Search guests</label><input type="search" id="guest-search" placeholder="Search name, contact, or host…" value="${e(filter.query)}"></div><label class="sr-only" for="service-filter">Filter by service</label><select id="service-filter"><option value="all">All services</option>${Object.keys(SERVICES).map(k=>`<option value="${k}" ${filter.service===k?'selected':''}>${SERVICES[k].name}</option>`).join('')}</select><label class="sr-only" for="status-filter">Filter by status</label><select id="status-filter"><option value="all">All statuses</option>${[...STATUSES,'due'].map(s=>`<option value="${s}" ${filter.status===s?'selected':''}>${s==='due'?'Overdue follow-up':s}</option>`).join('')}</select></div><div class="table-scroll"><table><caption class="sr-only">Illustrative guest plans and follow-up records</caption><thead><tr><th>Guest</th><th>Service & date</th><th>Status</th><th>Welcome host</th><th>Source</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody id="guest-rows">${guestRows()}</tbody></table></div><div class="table-foot"><span id="guest-count">${filteredGuests().length} of ${guests.length} demo guests</span><span>Saved in this browser</span></div></section>`,'guests');}
function refreshTable(){document.querySelector('#guest-rows').innerHTML=guestRows();document.querySelector('#guest-count').textContent=`${filteredGuests().length} of ${guests.length} demo guests`;}
function openOverlay(html,modal=false){lastFocus=document.activeElement;overlay.innerHTML=`<div class="overlay-backdrop ${modal?'modal-backdrop':''}"><section class="${modal?'modal':'drawer'}" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1">${html}</section></div>`;document.body.classList.add('no-scroll');overlay.querySelector('[role=dialog]').focus();}
function closeOverlay(){overlay.innerHTML='';document.body.classList.remove('no-scroll');currentGuest=null;if(lastFocus?.isConnected)lastFocus.focus();}
function guestDrawer(id){const g=guests.find(v=>v.id===id);if(!g)return;currentGuest=id;openOverlay(`<div class="drawer-header"><h2 id="dialog-title">Guest details</h2><button class="icon-btn" data-action="close" aria-label="Close guest details">${icon('close')}</button></div><div class="drawer-person"><span class="avatar">${e(initials(g.name))}</span><div><h3>${e(g.name)}</h3><p>${g.sample?'Illustrative sample record':'Visit created in this browser'}</p></div></div>${badge(g.status)}<div class="drawer-section"><div class="drawer-grid"><div class="drawer-detail"><small>Service</small><p>${SERVICES[g.service].name}</p></div><div class="drawer-detail"><small>Date & time</small><p>${dateLabel(g.date)} · ${SERVICES[g.service].time}</p></div><div class="drawer-detail"><small>Contact preference</small><p>${g.channel==='none'?'No contact requested':e(g.channel)}</p></div><div class="drawer-detail"><small>Contact details</small><p style="overflow-wrap:anywhere">${g.channel==='none'?'Not collected':e(g.contact)}</p></div><div class="drawer-detail"><small>Source</small><p>${e(g.source)}</p></div><div class="drawer-detail"><small>Host requested</small><p>${g.hostRequested?'Yes':'No'}</p></div></div>${g.question?`<div class="notice neutral" style="margin:18px 0 0"><strong>Arrival question</strong><br>${e(g.question)}</div>`:''}</div><div class="drawer-section"><h3>Welcome & next step</h3><form id="guest-update"><input type="hidden" name="id" value="${e(g.id)}"><div class="fields"><div class="field"><label for="guest-host">Assign a host</label><select id="guest-host" name="host">${HOSTS.map(h=>`<option ${h===g.host?'selected':''}>${h}</option>`).join('')}</select></div><div class="field"><label for="guest-status">Visit status</label><select id="guest-status" name="status">${STATUSES.map(s=>`<option ${s===g.status?'selected':''}>${s}</option>`).join('')}</select></div></div><p class="subtle" style="margin-top:12px">“Attended” records attendance now. “Connected” records a confirmed handoff. Canceling releases the assigned host.</p><button class="btn small" type="submit">Save changes ${icon('check')}</button></form>${g.status!=='Cancelled'?`<button class="btn outline small" data-action="follow-up" data-id="${e(g.id)}">${icon('heart')} Record follow-up outcome</button>`:''}${g.channel==='none'?'<p class="subtle" style="margin-top:10px">No outbound contact permission. Log in-person outcomes only.</p>':''}</div><div class="drawer-section"><h3>Activity history</h3>${(g.history||[]).map(h=>`<div class="timeline-entry">${e(h.text)}<small>${new Date(h.at).toLocaleString('en-US',{timeZone:TIMEZONE,dateStyle:'medium',timeStyle:'short'})} Chicago time</small></div>`).join('')}</div>`);currentGuest=id;}
function followUp(id){const g=guests.find(v=>v.id===id);openOverlay(`<div class="drawer-header"><h2 id="dialog-title">Record a follow-up</h2><button class="icon-btn" data-action="close" aria-label="Close">${icon('close')}</button></div><p>Log an outcome for ${e(g.name)}. This does not send a message.</p><form id="follow-up-form"><input type="hidden" name="id" value="${e(id)}"><div class="field"><label for="outcome">Outcome</label><select id="outcome" name="outcome">${(g.channel==='none'?['Spoke in person','Guest declined contact','Connect handoff confirmed']:['Contact completed','No response — try again','Guest declined contact','Connect handoff confirmed']).map(s=>`<option>${s}</option>`).join('')}</select></div><button class="btn form-submit" type="submit">Save outcome ${icon('check')}</button></form>`,true);}
function addGuest(){openOverlay(`<div class="drawer-header"><h2 id="dialog-title">Add a demo guest</h2><button class="icon-btn" data-action="close" aria-label="Close">${icon('close')}</button></div><p>Use sample details only. Save an upcoming visit, then update attendance in the guest record.</p>${planForm()}`,true);}
function calendarPage(){const today=chicagoDay(),monday=shiftDay(today,-((new Date(today+'T12:00:00Z').getUTCDay()+6)%7));const weeks=Array.from({length:6},(_,i)=>shiftDay(monday,i*7));return officeShell(`${officeHeading('The next six weeks','One shared outlook for people, rooms, and service readiness.',`<a class="btn outline small" href="#/office/invitations">${icon('invite')} Invitation kit</a>`)}<div class="notice neutral">Regular weekly services are generated in Chicago time. Dates and readiness checks are demo planning tools, not the official church calendar. Hosts, parking, and setup checks are saved in this browser.</div><div class="calendar-weeks">${weeks.map((week,i)=>`<div class="week-row"><div class="week-label">WEEK ${i+1}<strong>${dateLabel(week)}</strong></div>${[['friday',4],['sunday',6]].map(([k,offset])=>{const d=shiftDay(week,offset),key=`${k}-${d}`,checks=readiness[key]||{};return `<article class="calendar-card"><div class="cal-top"><h3>${SERVICES[k].name}</h3><span class="badge">${dateLabel(d,{weekday:'short',day:'numeric',month:'short'})}</span></div><p>${SERVICES[k].time} · Main gathering · ${guests.filter(g=>g.date===d&&g.service===k&&g.status!=='Cancelled').length} demo visits</p><div class="checklist">${[['hosts','Hosts ready'],['parking','Arrival ready'],['setup','Setup ready']].map(([id,label])=>`<label><input type="checkbox" data-readiness="${key}" data-check="${id}" ${checks[id]?'checked':''}>${label}</label>`).join('')}</div></article>`;}).join('')}</div>`).join('')}</div><div class="office-banner"><div><h3>A better weekly briefing.</h3><p>Member Services confirms guests and hosts. Facilities confirms arrival and setup. Calendar/Communications verifies service details. The Office Lead resolves gaps.</p></div></div>`,'calendar');}
function inviteLink(kind){const url=new URL(location.href);url.hash=`/plan?service=${kind}&source=member`;return url.href;}
function inviteMessage(kind){return `I’d love for you to join me at KingsWord Chicago this ${kind==='sunday'?'Sunday at 10:00 a.m.':'Friday at 7:30 p.m.'}! We meet at 4250 W Walton Street, Chicago. You can find visit details here: ${inviteLink(kind)}`;}
function invitationPage(){return officeShell(`${officeHeading('A personal invitation goes further.','Give members something useful to share—and a next step for every guest.') }<div class="notice neutral">These links open a public demo with browser-local sample data. Share them for review; they do not book a real visit or notify the church. Copying a message does not send it.</div><div class="invite-grid">${Object.keys(SERVICES).map(k=>`<article class="invite-card"><div class="invite-preview ${k}"><span class="invite-brand">KINGSWORD · CHICAGO</span><h2>${k==='sunday'?'There’s a place for you.':'Make space for faith.'}</h2><div><div class="invite-time">Every ${k==='sunday'?'Sunday · 10:00 AM':'Friday · 7:30 PM'}</div><div class="invite-address">4250 W Walton Street · Chicago</div></div></div><h3>${SERVICES[k].name} invitation</h3><p>${e(inviteMessage(k).split(' You can find')[0])}</p><div class="link-box">${e(inviteLink(k))}</div><div class="invite-actions"><button class="btn small" data-action="copy-message" data-service="${k}">${icon('copy')} Copy invitation</button><button class="btn outline small" data-action="copy-link" data-service="${k}">Copy link</button><a class="btn outline small" href="#/plan?service=${k}&source=member">Preview ${icon('arrow')}</a><button class="btn outline small" data-action="download-invite" data-service="${k}">${icon('download')} Save card</button></div></article>`).join('')}</div><div class="office-banner"><div><h3>Make it personal. Keep it simple.</h3><p>Add your own note, offer to meet your friend, and share the correct service link. Ask permission before collecting anyone else’s contact details.</p></div><button class="btn outline small" data-action="print">${icon('download')} Print invitation kit</button></div>`,'invitations');}
function settingsPage(){return officeShell(`${officeHeading('A working beginning.','What this version does—and what needs to connect before a real launch.')}<div class="settings-grid"><section class="panel settings-panel"><div class="eyebrow">Ready to try</div><h2 style="margin-top:15px">The demo workflow</h2><ul><li>Create a local department leader demo profile.</li><li>Add/edit team members and assign tasks.</li><li>Track task stages, due dates, and office oversight.</li><li>Plan a Sunday or Friday visit.</li><li>Assign a sample host and update visit status.</li><li>Record follow-up and Connect handoff outcomes.</li><li>Filter guests and export the current view.</li><li>Review six weeks and save readiness checks.</li><li>Copy service invitations and download a card.</li></ul><a class="btn outline small" href="#/plan">Try a guest visit ${icon('arrow')}</a></section><section class="panel settings-panel"><div class="eyebrow">Before going live</div><h2 style="margin-top:15px">Connect the real operation</h2><ul><li>Individual staff sign-in and role permissions.</li><li>Shared server database and recovery procedures.</li><li>Approved Breeze field mapping and synchronization.</li><li>Verified service exceptions and calendar ownership.</li><li>Approved contact channel and consent process.</li><li>Real host roster, audit controls, and launch testing.</li></ul><p>The office screens are a prototype, not a production access-control system. This public demo has no protected staff area. Use sample details only; no information is sent to the church.</p></section><section class="panel settings-panel"><h2>Local demo data</h2><p>${guests.length} guest records are currently in this browser session/storage. ${storageOK?'Browser storage is available.':'Browser storage is unavailable; changes are temporary.'} There is no shared database and no outbound messaging.</p><p style="margin-top:12px">Reset removes locally entered records and restores illustrative samples. Export first if you want to keep your demo work.</p><button class="btn outline small" data-action="reset">Reset demo data</button></section><section class="panel settings-panel"><h2>Office structure</h2><p><strong>Office Administrative Lead</strong> supervises Member & Volunteer Services; Facilities & Building Operations; and Calendar, Programs & Communications.</p><p style="margin-top:12px">The first build supports their common guest and service workflows. Workforce records, BT integration, resource publishing, and restricted Apostolic Office support follow after the pilot.</p><p style="margin-top:12px">Service details are based on the supplied proposal and the official Chicago website; confirm current exceptions with the office.</p></section></div>`,'settings');}
function render(){closeOverlay();document.querySelector('.sidebar')?.classList.remove('open');const {path}=route();const pages={'/':officeWorkspace,'/welcome':home,'/office/departments':departmentsPage,'/office/team':teamPage,'/office/tasks':tasksPage,'/office/leaders':leadersPage,'/visit/sunday':()=>visit('sunday'),'/visit/friday':()=>visit('friday'),'/plan':plan,'/office':officeWorkspace,'/office/guest-overview':overview,'/office/guests':guestPage,'/office/calendar':calendarPage,'/office/invitations':invitationPage,'/office/settings':settingsPage};const fn=pages[path];app.innerHTML=fn?fn():`${publicHeader()}<main id="main" class="wrap"><section class="success"><h1>Let’s get you back.</h1><p style="margin-top:20px">That page isn’t in this preview.</p><a class="btn" href="#/welcome">Back to welcome ${icon('arrow')}</a></section></main>${footer()}`;document.title=(path==='/'||path.startsWith('/office'))?'KingsWord · Church office demo':'KingsWord Chicago · A place to belong';window.scrollTo(0,0);}
function download(data,type,filename){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied. Make it your own before sharing.');}catch{openOverlay(`<div class="drawer-header"><h2 id="dialog-title">Copy your invitation</h2><button class="icon-btn" data-action="close" aria-label="Close">${icon('close')}</button></div><p>Clipboard access isn’t available. Select and copy the text below.</p><div class="field"><label for="manual-copy">Invitation text</label><textarea id="manual-copy" rows="7" readonly>${e(text)}</textarea></div>`,true);overlay.querySelector('textarea').select();}}
function invitationSVG(kind){const s=SERVICES[kind],dark=kind==='sunday',bg=dark?'#112f3b':'#e9ecdf',fg=dark?'#f7f6f1':'#112f3b';return `<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1350" viewBox="0 0 1080 1350"><rect width="1080" height="1350" fill="${bg}"/><g fill="none" stroke="#be9d59" opacity=".4">${Array.from({length:9},(_,i)=>`<ellipse cx="980" cy="300" rx="${170+i*30}" ry="${260+i*35}"/>`).join('')}</g><g font-family="Arial,sans-serif" fill="${fg}"><text x="80" y="130" font-size="26" letter-spacing="5">KINGSWORD CHICAGO</text><text x="80" y="520" font-size="94">${dark?'There’s a place':'Make space'}</text><text x="80" y="635" font-size="94">${dark?'for you.':'for faith.'}</text><text x="80" y="940" font-size="40">${dark?'Sundays · 10:00 AM':'Fridays · 7:30 PM'}</text><text x="80" y="1020" font-size="29">4250 W Walton Street, Chicago</text><text x="80" y="1160" font-size="24">chicago.kingsword.org</text><text x="80" y="1260" font-size="18" opacity=".65">DESIGN PREVIEW · Confirm service details before distribution</text></g></svg>`;}
document.addEventListener('click',event=>{
 const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id,kind=el.dataset.service;
 if(handleWorkspaceAction(action,el))return;
 if(action==='skip-main'){event.preventDefault();const main=document.querySelector('#main');main?.setAttribute('tabindex','-1');main?.focus();}
 else if(action==='services'){event.preventDefault();document.querySelector('#services')?.scrollIntoView({behavior:'smooth'});}
 else if(action==='menu'){const menu=document.querySelector('.sidebar');menu.classList.toggle('open');el.setAttribute('aria-expanded',menu.classList.contains('open'));}
 else if(action==='calendar'){download(calendarFile(kind,el.dataset.date),'text/calendar;charset=utf-8',`kingsword-${kind}-${el.dataset.date}.ics`);toast('Calendar downloaded. End time is a planning placeholder.');}
 else if(action==='guest')guestDrawer(id);
 else if(action==='close')closeOverlay();
 else if(action==='add-guest')addGuest();
 else if(action==='follow-up')followUp(id);
 else if(action==='export'){const rows=filteredGuests();download(safeCSV([['Name','Service','Date','Status','Host','Source','Contact preference','Contact','Visit contact permission'],...rows.map(g=>[g.name,g.service,g.date,g.status,g.host,g.source,g.channel,g.contact,g.consent?'Yes':'No'])]),'text/csv;charset=utf-8','kingsword-demo-guests.csv');toast(`Exported ${rows.length} demo records from this view.`);}
 else if(action==='clear-filters'){filter={query:'',service:'all',status:'all'};render();}
 else if(action==='copy-message')copy(inviteMessage(kind));
 else if(action==='copy-link')copy(inviteLink(kind));
 else if(action==='download-invite'){download(invitationSVG(kind),'image/svg+xml',`kingsword-${kind}-invitation-preview.svg`);toast('Invitation design downloaded. Review before distribution.');}
 else if(action==='print')window.print();
 else if(action==='cancel-own'){const g=guests.find(g=>g.id===id);if(g){saveGuest(updateGuest(g,{status:'Cancelled'}));document.querySelector('#plan-card').innerHTML=`<div class="success"><h2>Demo visit canceled.</h2><p style="margin-top:20px">The host assignment has been released in this browser. No messages were sent.</p><a class="btn" href="#/plan">Plan another demo visit</a></div>`;toast('Demo visit canceled.');}}
 else if(action==='reset'){openOverlay(`<div class="drawer-header"><h2 id="dialog-title">Reset this browser’s demo?</h2><button class="icon-btn" data-action="close" aria-label="Close">${icon('close')}</button></div><p>This removes locally entered guest plans, department profiles, team members, tasks, follow-up history, and readiness checks, then restores sample records. It affects only this browser.</p><div class="confirmation-actions"><button class="btn" data-action="confirm-reset">Reset demo data</button><button class="btn outline" data-action="close">Keep my changes</button></div>`,true);}
 else if(action==='confirm-reset'){guests=seed();readiness={};workspace=seedWorkspace();saveWorkspace();persist();write(READY_KEY,{});closeOverlay();render();toast('Sample records restored.');}
});
document.addEventListener('change',event=>{const el=event.target;
 if(el.id==='team-department'){go('/office/team?department='+encodeURIComponent(el.value));}
 if(el.id==='task-department'){go('/office/tasks?department='+encodeURIComponent(el.value));}
 if(el.id==='task-priority-filter'){taskFilter=el.value;render();}
 if(el.dataset.taskStatus){const task=workspace.tasks.find(t=>t.id===el.dataset.taskStatus);if(task&&TASK_STATUSES.includes(el.value)&&(!activeLeader()||activeLeader().departmentId===task.departmentId)){task.status=el.value;task.updatedAt=new Date().toISOString();saveWorkspace();render();toast('Task status updated.');}}
 if(el.id==='plan-service'){const form=el.form;form.querySelector('[name=date]').innerHTML=dateOptions(el.value);}
 if(el.id==='plan-channel'){const form=el.form,no=el.value==='none',input=form.querySelector('[name=contact]');form.querySelector('#contact-field').hidden=no;form.querySelector('#consent-field').hidden=no;input.type=el.value==='phone'?'tel':'email';input.autocomplete=el.value==='phone'?'tel':'email';form.querySelector('#contact-label').textContent=el.value==='phone'?'Phone number':'Email address';input.placeholder=el.value==='phone'?'Use a sample number':'you@example.com';if(no){input.value='';form.querySelector('[name=consent]').checked=false;}}
 if(el.id==='service-filter'){filter.service=el.value;refreshTable();}
 if(el.id==='status-filter'){filter.status=el.value;refreshTable();}
 if(el.dataset.readiness){const k=el.dataset.readiness;readiness[k]={...(readiness[k]||{}),[el.dataset.check]:el.checked};write(READY_KEY,readiness);toast('Service readiness updated in this browser.');}
});
document.addEventListener('input',event=>{if(event.target.id==='guest-search'){filter.query=event.target.value;refreshTable();}});
document.addEventListener('submit',event=>{
 const form=event.target;if(['leader-form','member-form','task-form'].includes(form.id)){event.preventDefault();handleWorkspaceSubmit(form);return;}if(!['plan-form','guest-update','follow-up-form'].includes(form.id))return;event.preventDefault();const values=Object.fromEntries(new FormData(form));
 if(form.id==='plan-form'){
  values.hostRequested=!!values.hostRequested;values.consent=!!values.consent;values.name=values.name.trim();values.contact=values.channel==='none'?'':values.contact.trim();const errors=validatePlan(values);form.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));form.querySelectorAll('.error').forEach(el=>el.remove());
  if(Object.keys(errors).length){form.querySelector('#plan-errors').innerHTML='<div class="notice">Please check the highlighted details below.</div>';for(const [key,error]of Object.entries(errors)){const field=form.elements.namedItem(key);if(field){field.setAttribute('aria-invalid','true');field.insertAdjacentHTML('afterend',`<span class="error">${e(error)}</span>`);}}form.elements.namedItem(Object.keys(errors)[0])?.focus();return;}
  const duplicate=values.channel!=='none'&&guests.find(g=>g.service===values.service&&g.date===values.date&&g.contact.toLowerCase()===values.contact.toLowerCase()&&g.status!=='Cancelled');
  if(duplicate){toast('A demo visit already exists for this contact and service date.');form.querySelector('#plan-errors').innerHTML='<div class="notice">This contact already has a demo visit for that service date. You can review it in the office demo.</div>';return;}
  const now=new Date().toISOString(),g={...values,id:globalThis.crypto?.randomUUID?.()||`visit-${Date.now()}-${Math.random().toString(36).slice(2)}`,host:'Unassigned',status:'Planned',createdAt:now,history:[{at:now,text:'Demo visit planned. Contact preference recorded.'}]};saveGuest(g);if(overlay.contains(form)){closeOverlay();render();toast('Demo guest added to the office queue.');}else publicSuccess(g);
 }
 if(form.id==='guest-update'){const g=guests.find(g=>g.id===values.id);if(!g)return;if(!STATUSES.includes(values.status)||!HOSTS.includes(values.host))return;if(['Follow-up','Connected'].includes(values.status)&&!g.attendedAt){toast('Confirm attendance before a follow-up or Connect handoff.');return;}let next=updateGuest(g,{host:values.host,status:values.status});if(values.status==='Connected')next.followedUpAt=next.followedUpAt||new Date().toISOString();saveGuest(next);closeOverlay();render();toast('Guest details updated.');}
 if(form.id==='follow-up-form'){const g=guests.find(g=>g.id===values.id);if(!g)return;if(!g.attendedAt){toast('Confirm attendance before recording a post-visit follow-up.');return;}const now=new Date().toISOString(),changes={status:values.outcome==='Connect handoff confirmed'?'Connected':'Follow-up'};if(values.outcome!=='No response — try again')changes.followedUpAt=now;if(values.outcome==='Guest declined contact'){changes.channel='none';changes.consent=false;changes.contact='';}const next=updateGuest(g,changes);next.history.unshift({at:now,text:values.outcome});saveGuest(next);closeOverlay();render();toast('Follow-up outcome recorded.');}
});
overlay.addEventListener('click',ev=>{if(ev.target.classList.contains('overlay-backdrop'))closeOverlay();});
document.addEventListener('keydown',event=>{if(!overlay.firstChild)return;if(event.key==='Escape'){closeOverlay();return;}if(event.key==='Tab'){const els=[...overlay.querySelectorAll('button,a,input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled&&!el.closest('[hidden]'));if(!els.length)return;const first=els[0],last=els.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===overlay.querySelector('[role=dialog]'))){event.preventDefault();last.focus();}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===overlay.querySelector('[role=dialog]'))){event.preventDefault();first.focus();}}});
window.addEventListener('hashchange',render);render();

window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
if('serviceWorker' in navigator && ['https:','http:'].includes(location.protocol))navigator.serviceWorker.register('./sw.js').catch(()=>console.info('Offline support unavailable; online demo remains usable.'));
